fix_code:
public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    long x = sc.nextLong();
    if (x % 10 == 0) {
        System.out.println(x / 10);
    } else {
        if (x > 0) {
            System.out.println(x / 10 + 1);
        } else {
            System.out.println(x / 10);
        }
    }
}

